Body:
Mini and hacky, but maybe it's worth mentioning/sharing that it's possible to modify system prompt using [plugin](https://opencode.ai/docs/plugins) system. You can use the "experimental.chat.system.transform" hook to replace or modify the system prompt at runtime. Something like (`.opencode/plugins/slim-prompt.ts`):
```ts
import type { Plugin } from "@opencode-ai/plugin"
import { readFileSync } from "fs"
import { join } from "path"

export const SlimPromptPlugin: Plugin = async () => {
  return {
    "experimental.chat.system.transform": async (input, output) => {
      // Hacky way to check if agent is "plan" or "build" (not "title"). Seems like there's no better way right now (no `input.agent`)
      if (!output.system[0].includes("You are opencode")) return

      const shortPrompt = readFileSync(join(__dirname, "prompt.txt"), "utf8")

      // system[0] is base prompt + environment + skills + instructions (AGENTS.md), all joined
      // Let's say we want just short prompt + environment only (no skills)
      // Environment block is identifiable by its XML tags
      const envMatch = output.system[0].match(/<env>[\s\S]*?<\/env>/)
      const envBlock = envMatch ? "Here is some useful information about the environment you are running in:\n" + envMatch[0] : ""

      output.system[0] = [shortPrompt, envBlock].join("\n\n")
    },
  }
}

```
